import Foundation

enum SHA256FileHasher {
    private static let chunkSize = 4 * 1_024 * 1_024

    static func sha256Hex(for fileURL: URL) throws -> String {
        let fileManager = FileManager.default
        guard fileManager.fileExists(atPath: fileURL.path) else {
            throw ModelStorageError.fileNotFound(fileURL)
        }
        guard fileManager.isReadableFile(atPath: fileURL.path) else {
            throw ModelStorageError.unreadableFile(fileURL)
        }

        let handle: FileHandle
        do {
            handle = try FileHandle(forReadingFrom: fileURL)
        } catch {
            throw ModelStorageError.unreadableFile(fileURL)
        }
        defer {
            try? handle.close()
        }

        var hasher = SHA256()
        do {
            while true {
                guard let data = try handle.read(upToCount: chunkSize), !data.isEmpty else {
                    break
                }
                hasher.update(data: data)
            }
        } catch {
            throw ModelStorageError.unreadableFile(fileURL)
        }

        return hasher.finalize().map { String(format: "%02x", $0) }.joined()
    }
}","imports":["CryptoKit","Foundation"],"language":"swift","module":"Services/LLM/Models","path":"ios/Lumen/Services/LLM/Models/SHA256FileHasher.swift","responsibility":"`ios/Lumen/Services/LLM/Models/SHA256FileHasher.swift` owns SHA256FileHasher behavior and defines: SHA256FileHasher, sha256Hex, chunkSize, fileManager, handle, hasher, data.","sourceHash":"9697cde680ec6562954f1aa152d21b0a06cea5dd7d051cb28887ba576b8a8508","symbols":["SHA256FileHasher","sha256Hex","chunkSize","fileManager","handle","hasher","data"]}

